<script setup lang="ts">import {Head,Link,useForm} from '@inertiajs/vue3';import PageHeader from '@/components/Shared/PageHeader.vue';import RichTextEditor from '@/components/admin/RichTextEditor.vue';import {Button} from '@/components/ui/button';const p=defineProps<{entry:any|null;registry:any[];audiences:any[];roles:any[];permissions:any[]}>();const form=useForm({page_key:p.entry?.page_key??'',title:p.entry?.title??'',summary:p.entry?.summary??'',content:p.entry?.content??'',audience:p.entry?.audience??'all',is_active:p.entry?.is_active??true,is_published:p.entry?.is_published??false,published_at:p.entry?.published_at??null,sort_order:p.entry?.sort_order??0,role_ids:p.entry?.roles?.map((x:any)=>x.id)??[],permission_ids:p.entry?.permissions?.map((x:any)=>x.id)??[]});function submit(){p.entry?form.put(`/admin/page-help/${p.entry.id}`):form.post('/admin/page-help');}</script>
<template><Head :title="entry?'Edit Page Help':'Create Page Help'"/><div class="space-y-6 p-6"><PageHeader :title="entry?'Edit Page Help':'Create Page Help'" description="Define contextual documentation and its audience"><template #actions><Button variant="outline" as-child><Link href="/admin/page-help">Back</Link></Button></template></PageHeader><form class="space-y-6" @submit.prevent="submit"><div class="grid gap-5 rounded-lg border bg-card p-5 md:grid-cols-2"><label class="space-y-2"><span class="text-sm font-medium">Page key</span><input v-model="form.page_key" list="page-help-keys" class="h-10 w-full rounded-md border bg-background px-3" required/><datalist id="page-help-keys"><option v-for="x in registry" :key="x.key" :value="x.key">{{x.name}}</option></datalist><p class="text-xs text-destructive">{{form.errors.page_key}}</p></label><label class="space-y-2"><span class="text-sm font-medium">Title</span><input v-model="form.title" class="h-10 w-full rounded-md border bg-background px-3" required/></label><label class="space-y-2 md:col-span-2"><span class="text-sm font-medium">Summary</span><textarea v-model="form.summary" class="min-h-20 w-full rounded-md border bg-background p-3"/></label><label class="space-y-2"><span class="text-sm font-medium">Audience</span><select v-model="form.audience" class="h-10 w-full rounded-md border bg-background px-3"><option v-for="a in audiences" :value="a.value">{{a.label}}</option></select></label><label class="space-y-2"><span class="text-sm font-medium">Sort order</span><input v-model.number="form.sort_order" type="number" min="0" class="h-10 w-full rounded-md border bg-background px-3"/></label><div class="flex flex-wrap gap-6 md:col-span-2"><label class="flex items-center gap-2"><input v-model="form.is_active" type="checkbox"/> Active</label><label class="flex items-center gap-2"><input v-model="form.is_published" type="checkbox"/> Published</label></div></div><div class="rounded-lg border bg-card p-5"><h2 class="mb-3 font-semibold">Help content</h2><RichTextEditor v-model="form.content"/><p class="mt-2 text-xs text-destructive">{{form.errors.content}}</p></div><div v-if="form.audience==='custom'" class="grid gap-5 rounded-lg border bg-card p-5 lg:grid-cols-2"><div><h2 class="mb-3 font-semibold">Roles</h2><label v-for="r in roles" :key="r.id" class="mb-2 flex items-center gap-2"><input v-model="form.role_ids" type="checkbox" :value="r.id"/>{{r.label}}</label></div><div><h2 class="mb-3 font-semibold">Permissions</h2><label v-for="x in permissions" :key="x.id" class="mb-2 flex items-center gap-2"><input v-model="form.permission_ids" type="checkbox" :value="x.id"/>{{x.group_name}} — {{x.label}}</label></div></div><div class="flex justify-end"><Button :disabled="form.processing">{{entry?'Save changes':'Create entry'}}</Button></div></form></div></template>
